return ['domain'=>'mrz-display-post-exp','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'fr_FR','project-id-version'=>'MRZ Display Post Exp 1.3.1','pot-creation-date'=>'2026-10-31T16:35:36+00:00','po-revision-date'=>'2026-10-31 16:35+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['MRZ Display Post Exp'=>'MRZ Display Post Exp','https://github.com/m0r3z/mrz-display-post-exp'=>'https://github.com/m0r3z/mrz-display-post-exp','Morez.co'=>'Morez.co','https://morez.co'=>'https://morez.co','Display format'=>'Format d\'affichage','List'=>'Liste','Grid'=>'Grille','Slider'=>'Slider','Featured image aspect ratio'=>'Ratio de l\'image à la une','Auto (original image)'=>'Auto (image d\'origine)','Square (1:1)'=>'Carré (1:1)','Landscape 4:3'=>'Paysage 4:3','Landscape 3:2'=>'Paysage 3:2','Landscape 16:9'=>'Paysage 16:9','Portrait 3:4'=>'Portrait 3:4','Portrait 2:3'=>'Portrait 2:3','Applies to the featured image ({post_thumbnail}). The image fills the area and is cleanly cropped (object-fit) without distortion and without altering the file.'=>'S\'applique à l\'image à la une ({post_thumbnail}). L\'image remplit la zone et est recadrée proprement (object-fit) sans déformation, sans modifier le fichier.','Minimum column width (px)'=>'Largeur min. d\'une colonne (px)','The grid automatically fits as many columns as possible based on this minimum width.'=>'La grille remplit automatiquement autant de colonnes que possible à partir de cette largeur minimale.','Gap between items (px)'=>'Espacement entre items (px)','Horizontal and vertical spacing between grid items.'=>'Écart horizontal et vertical entre les items de la grille.','Visible items (slider)'=>'Items visibles (slider)','Desktop:'=>'Bureau :','Tablet:'=>'Tablette :','Mobile:'=>'Mobile :','Desktop > 1024px, tablet ≤ 1024px, mobile ≤ 768px.'=>'Bureau > 1024px, tablette ≤ 1024px, mobile ≤ 768px.','Transition speed (ms)'=>'Vitesse de transition (ms)','Duration of the slide animation when clicking the arrows / dots and during autoplay. The higher the value, the slower and smoother the transition (default: 500 ms). Touch swiping remains native.'=>'Durée du glissement au clic des flèches / puces et en défilement automatique. Plus la valeur est élevée, plus la transition est lente et douce (défaut : 500 ms). Le glissement au doigt reste natif.','Slider options'=>'Options du slider','Show previous / next arrows.'=>'Afficher les flèches précédent / suivant.','Arrow position:'=>'Position des flèches :','On the sides'=>'Sur les côtés','Above (left-aligned)'=>'Au-dessus (alignées à gauche)','Show pagination dots.'=>'Afficher les puces de pagination.','Loop (go back to the start after the last item).'=>'Boucler (revenir au début après le dernier item).','Autoplay.'=>'Défilement automatique.','Delay between transitions (ms):'=>'Délai entre transitions (ms) :','Autoplay respects the visitor\'s “reduce motion” preference and pauses on hover.'=>'Le défilement automatique respecte la préférence « réduire les animations » du visiteur et se met en pause au survol.','Filters layout'=>'Layout des filtres','Above'=>'Au-dessus','Left'=>'À gauche','Right'=>'À droite','Only applies when filters or search are enabled.'=>'N\'a d\'effet que si des filtres ou la recherche sont activés.','On item click'=>'Clic sur un item','Do nothing'=>'Ne rien faire','Open the post page'=>'Ouvrir la page du post','Reset button'=>'Bouton de réinitialisation','Show a button that resets all filters.'=>'Afficher un bouton de réinitialisation de tous les filtres.','Button text:'=>'Texte du bouton :','Clear'=>'Effacer','Drag to reorder'=>'Glisser pour réordonner','Dropdown'=>'Menu déroulant','Radio buttons'=>'Boutons radio','Checkboxes'=>'Cases à cocher','OR'=>'OU','AND'=>'ET','Taxonomy'=>'Taxonomie','Display label'=>'Libellé affiché','Filter type'=>'Type de filtre','Logic'=>'Logique','How checked options are combined'=>'Combinaison entre cases cochées','ACF field'=>'Champ ACF','Listing type'=>'Type d\'annonce','How checked options are combined (no effect in dropdown/radio mode)'=>'Combinaison entre cases cochées (sans effet en mode dropdown/radio)','Remove'=>'Retirer','settings section titleSearch'=>'Recherche','Show a search field (instant client-side filtering).'=>'Afficher un champ de recherche (filtrage instantané côté client).','ACF fields to include in search:'=>'Champs ACF à inclure dans la recherche :','Comma-separated list of ACF text field names. The post title is always included.'=>'Liste de noms de champs ACF texte séparés par des virgules. Le titre du post est toujours inclus.','Field position:'=>'Position du champ :','Inside the filters block'=>'Dans le bloc filtres','At the top, full width'=>'En haut, pleine largeur','Label shown above the field:'=>'Libellé affiché au-dessus du champ :','Search'=>'Rechercher','Field placeholder:'=>'Placeholder du champ :','Search…'=>'Rechercher…','Global options'=>'Options globales','Show the number of results next to each filter option.'=>'Afficher le nombre de résultats à côté de chaque option de filtre.','Sync filters with the URL (shareable link).'=>'Synchroniser les filtres avec l\'URL (lien partageable).','Filters'=>'Filtres','Check the taxonomies and add the ACF fields to offer as filters, then drag the rows (⠿) to set their display order on the site.'=>'Cochez les taxonomies et ajoutez les champs ACF à proposer en filtre, puis glissez les lignes (⠿) pour définir leur ordre d\'affichage sur le site.','Add ACF filter'=>'Ajouter un filtre ACF','Only taxonomies attached to the selected post type are shown. The label replaces the taxonomy name displayed above the filter on the site.'=>'Seules les taxonomies liées au post type sélectionné sont affichées. Le libellé remplace le nom de la taxonomie affiché au-dessus du filtre sur le site.','For Select, Radio Button, Checkbox or True / False fields, options are detected automatically from the ACF configuration. For other types (text, number), distinct values are collected dynamically from the posts.'=>'Pour les champs Select, Radio, Checkbox ou Vrai/Faux, les options sont détectées automatiquement depuis la configuration ACF. Pour les autres types (texte, nombre), les valeurs distinctes des posts sont collectées dynamiquement.','Paste this shortcode into your content:'=>'Collez ce shortcode dans vos contenus :','Example with a forced filter:'=>'Exemple avec filtre forcé :','Publish date'=>'Date de publication','Title'=>'Titre','Manual order (menu_order)'=>'Ordre manuel (menu_order)','Random'=>'Aléatoire','Last modified date'=>'Date de modification','ACF date field (events)'=>'Champ ACF de date (agenda)','Source post type'=>'Post type source','The post type whose entries will be displayed.'=>'Le post type dont les entrées seront affichées.','Order by'=>'Trier par','Descending'=>'Décroissant','Ascending'=>'Croissant','ACF date field'=>'Champ ACF de date','Name of the ACF Date Picker (or Date Time Picker) field used for sorting. Only entries that have this field will be displayed.'=>'Nom du champ ACF de type Date (ou Date/Heure) servant au tri. Seules les entrées possédant ce champ seront affichées.','Show'=>'Afficher','All dates'=>'Toutes les dates','Upcoming only (≥ today)'=>'À venir uniquement (≥ aujourd\'hui)','Past only (< today)'=>'Passées uniquement (< aujourd\'hui)','Server-side filter on the date field above. “Upcoming” hides past events (ideal for an events calendar).'=>'Filtre côté serveur sur le champ de date ci-dessus. « À venir » masque les événements passés (idéal agenda).','Maximum number of posts'=>'Nombre max de posts','Server-side loading limit. 0 = unlimited.'=>'Limite de chargement côté serveur. 0 = illimité.','Posts per page'=>'Posts par page','Client-side pagination (list and grid): number of posts per page. 0 = show all. Ignored in slider mode.'=>'Pagination côté utilisateur (liste et grille) : nombre de posts par page. 0 = tous affichés. Ignoré en mode slider.','Current context'=>'Contexte courant','Only show content sharing the category of the current page (single post or category archive).'=>'N\'afficher que les contenus partageant la catégorie de la page courante (single ou archive de catégorie).','Ideal for a “related content” block placed in a post: on a single post, the current item is excluded. Without a category context (e.g. a page), all content is displayed.'=>'Idéal pour un bloc « contenus liés » placé dans un article : sur un single, l\'élément courant est exclu. Sans contexte de catégorie (ex. page), tous les contenus s\'affichent.','Context taxonomy'=>'Taxonomie du contexte','Taxonomy shared by the current page and the displayed content (default: Category).'=>'Taxonomie partagée entre la page courante et les contenus affichés (par défaut : Catégorie).','Item template'=>'Template de l\'item','HTML rendered for each entry (list, grid or slider). The style attribute is not allowed: use your theme\'s CSS for styling.'=>'HTML affiché pour chaque entrée (liste, grille ou slider). L\'attribut style n\'est pas autorisé : mettez en forme via le CSS de votre thème.','Post title.'=>'Titre du post.','Post link (permalink).'=>'Lien (permalien) du post.','Full excerpt.'=>'Extrait complet.','Excerpt trimmed to N words (25 here).'=>'Extrait tronqué à N mots (ici 25).','Featured image (<img> tag).'=>'Image à la une (balise <img>).','Featured image URL.'=>'URL de l\'image à la une.','Post ID.'=>'Identifiant du post.','Post publish date (site date format).'=>'Date de publication du post (format de date du site).','Value of an ACF field (replace “nom_champ_acf” with your field name).'=>'Valeur d\'un champ ACF (remplacez « nom_champ_acf » par le nom de votre champ).','All terms of the taxonomy, each wrapped in a <span class="mrz-dpe-term">.'=>'Tous les termes de la taxonomie, chacun dans un <span class="mrz-dpe-term">.','Name of the first term only (plain text).'=>'Nom du premier terme uniquement (texte brut).','Slug of the first term (e.g. “research-development”) — handy as a CSS class modifier.'=>'Slug du premier terme (ex. « recherche-developpement ») — idéal comme modificateur de classe CSS.','ACF date field split into 3 spans: day / month / year (see formats below).'=>'Champ ACF de date découpé en 3 spans : jour / mois / année (voir formats ci-dessous).','Month as a number: 08 (default).'=>'Mois en numéro : 08 (par défaut).','Month as a number without leading zero: 8.'=>'Mois en numéro sans zéro : 8.','Full month name, localized: August.'=>'Mois en toutes lettres, localisé : août.','Abbreviated month name, localized: Aug.'=>'Mois abrégé, localisé : aoû.','Available placeholders, date formats & conditionals'=>'Placeholders disponibles, formats de date & conditionnels','Available placeholders'=>'Placeholders disponibles','Date formats ({acf_date})'=>'Formats de date ({acf_date})','The day (01) and year (2026) are fixed; only the month changes based on the suffix:'=>'Le jour (01) et l\'année (2026) sont fixes ; seul le mois change selon le suffixe :','Each part is wrapped in its own span: <code>.mrz-dpe-day</code>, <code>.mrz-dpe-month</code>, <code>.mrz-dpe-year</code> — style them with your theme\'s CSS.'=>'Chaque partie est dans son span : <code>.mrz-dpe-day</code>, <code>.mrz-dpe-month</code>, <code>.mrz-dpe-year</code> — à styliser via le CSS de votre thème.','Conditionals'=>'Conditionnels','Displays a block only if the field has a value: <code>{#if %mon_champ%}&lt;div&gt;...&lt;/div&gt;{/if}</code>. Also works with <code>{#if post_thumbnail}…{/if}</code> or <code>{#if taxonomy:category}…{/if}</code>.'=>'Affiche un bloc seulement si le champ est renseigné : <code>{#if %mon_champ%}&lt;div&gt;...&lt;/div&gt;{/if}</code>. Fonctionne aussi avec <code>{#if post_thumbnail}…{/if}</code> ou <code>{#if taxonomy:category}…{/if}</code>.','MRZ Display Post Exp requires Advanced Custom Fields (Pro recommended). Please install and activate ACF before activating this plugin.'=>'MRZ Display Post Exp nécessite Advanced Custom Fields (Pro recommandé). Veuillez installer et activer ACF avant d\'activer ce plugin.','Missing dependency'=>'Dépendance manquante','post type general nameMRZ Display Post'=>'MRZ Display Post','post type singular nameItem'=>'Élément','admin menuMRZ Display Post'=>'MRZ Display Post','add new on admin barItem'=>'Élément','Add new item'=>'Ajouter un élément','New item'=>'Nouvel élément','Edit item'=>'Modifier l\'élément','View item'=>'Voir l\'élément','All items'=>'Tous les éléments','Search items'=>'Rechercher un élément','No items found.'=>'Aucun élément trouvé.','No items found in Trash.'=>'Aucun élément dans la corbeille.','Shortcode'=>'Shortcode','Yes'=>'Oui','No'=>'Non','Data source'=>'Source des données','HTML template'=>'Template HTML','Filters & search'=>'Filtres & recherche','Display'=>'Affichage','MRZ Display Post Exp requires Advanced Custom Fields (Pro recommended) to work.'=>'MRZ Display Post Exp nécessite Advanced Custom Fields (Pro recommandé) pour fonctionner.','All'=>'Tous','Previous'=>'Précédent','Next'=>'Suivant','Previous page'=>'Page précédente','Next page'=>'Page suivante','Display posts and custom posts with their ACF fields as a list, grid or slider, with customizable HTML templates, client-side filters and search.'=>'Affiche des posts et custom posts avec leurs champs ACF en liste, grille ou slider. Templates HTML personnalisables, filtres et recherche côté client.','No results.'=>'Aucun résultat.']];